using System.Drawing.Drawing2D;
using System.Net.NetworkInformation;
using System.Runtime.InteropServices;
namespace PurpleStream;
static class Ui {
 public static Color Background=Color.FromArgb(16,17,40),Surface=Color.FromArgb(28,23,51),Text=Color.FromArgb(231,232,245),Muted=Color.FromArgb(166,170,195);
 public static GraphicsPath Round(RectangleF r,float radius){var p=new GraphicsPath();float d=Math.Min(radius*2,Math.Min(r.Width,r.Height));p.AddArc(r.X,r.Y,d,d,180,90);p.AddArc(r.Right-d,r.Y,d,d,270,90);p.AddArc(r.Right-d,r.Bottom-d,d,d,0,90);p.AddArc(r.X,r.Bottom-d,d,d,90,90);p.CloseFigure();return p;}
 public static Button Button(string label,Action action){var b=new Button{Text=label,AutoSize=true,Height=34,Padding=new(9,3,9,3),FlatStyle=FlatStyle.Flat,BackColor=Color.FromArgb(53,44,82),ForeColor=Text,Font=new("Segoe UI",10)};b.FlatAppearance.BorderSize=0;b.Click+=(_,_)=>action();return b;}
 public static Label Label(string text,int height=30)=>new(){Text=text,ForeColor=Text,Height=height,Dock=DockStyle.Top,Padding=new(8,4,4,0),AutoEllipsis=true};
 public static string Clock(long ms){var t=TimeSpan.FromMilliseconds(Math.Max(0,ms));return t.TotalHours>=1?$"{(int)t.TotalHours}:{t.Minutes:00}:{t.Seconds:00}":$"{t.Minutes:00}:{t.Seconds:00}";}
 public static void Dark(Form form){form.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);form.BackColor=Background;form.ForeColor=Text;form.Font=new("Segoe UI",10);form.StartPosition=FormStartPosition.CenterParent;}
}
class GradientPanel:Panel {public GradientPanel(){DoubleBuffered=true;}protected override void OnPaintBackground(PaintEventArgs e){using var b=new LinearGradientBrush(ClientRectangle,Color.FromArgb(20,32,53),Color.FromArgb(29,10,49),25f);e.Graphics.FillRectangle(b,ClientRectangle);}}
class RoundedPanel:Panel {public Color Fill{get;set;}=Ui.Surface;public RoundedPanel(){DoubleBuffered=true;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;}protected override void OnPaint(PaintEventArgs e){e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;using var path=Ui.Round(new RectangleF(1,1,Width-3,Height-3),22);using var brush=new SolidBrush(Fill);using var pen=new Pen(Color.FromArgb(68,66,91),1.5f);e.Graphics.FillPath(brush,path);e.Graphics.DrawPath(pen,path);base.OnPaint(e);}}
class Tile:Button {
 public Color First{get;set;}public Color Last{get;set;}public string Glyph{get;set;}="▶";bool hover;
 protected override void OnResize(EventArgs e){base.OnResize(e);if(Width>8&&Height>8){using var path=Ui.Round(new(3,3,Width-7,Height-7),28);Region=new Region(path);}}
 public Tile(){CausesValidation=false;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;UseVisualStyleBackColor=false;DoubleBuffered=true;Cursor=Cursors.Hand;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;MouseEnter+=(_,_)=>{hover=true;Invalidate();};MouseLeave+=(_,_)=>{hover=false;Invalidate();};}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using var path=Ui.Round(new(3,3,Width-7,Height-7),28);using var gradient=new LinearGradientBrush(ClientRectangle,First,Last,30f);g.FillPath(gradient,path);if(hover){using var pen=new Pen(Color.FromArgb(180,210,210,255),2);g.DrawPath(pen,path);}float size=Math.Min(92,Height*.42f);var circle=new RectangleF((Width-size)/2,Height*.12f,size,size);using var halo=new SolidBrush(Color.FromArgb(32,255,255,255));g.FillEllipse(halo,circle);using var icon=new Font("Segoe UI Symbol",size*.38f,FontStyle.Regular);using var white=new SolidBrush(Color.White);using var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center};if(Height<110){using var small=new Font("Segoe UI",15,FontStyle.Bold);g.DrawString(Text,small,white,ClientRectangle,format);return;}g.DrawString(Glyph,icon,white,circle,format);using var font=new Font("Segoe UI",Math.Max(13,Math.Min(23,Width/12)),FontStyle.Bold);g.DrawString(Text,font,white,new RectangleF(4,Height*.66f,Width-8,Height*.25f),format);}
}
class CircleTool:Button {protected override void OnResize(EventArgs e){base.OnResize(e);if(Width>6&&Height>6){using var path=new GraphicsPath();path.AddEllipse(2,2,Width-5,Height-5);Region=new Region(path);}}readonly string symbol;readonly ToolTip tip=new();bool hover;public CircleTool(string glyph,string title,Action click){symbol=glyph;CausesValidation=false;FlatStyle=FlatStyle.Flat;FlatAppearance.BorderSize=0;UseVisualStyleBackColor=false;SetStyle(ControlStyles.SupportsTransparentBackColor,true);BackColor=Color.Transparent;AccessibleName=title;AccessibleRole=AccessibleRole.PushButton;Size=new(56,56);Margin=new(5,6,5,6);Cursor=Cursors.Hand;DoubleBuffered=true;tip.SetToolTip(this,title);Click+=(_,_)=>click();MouseEnter+=(_,_)=>{hover=true;Invalidate();};MouseLeave+=(_,_)=>{hover=false;Invalidate();};}protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using var b=new SolidBrush(Color.FromArgb(61,55,83));using var p=new Pen(hover?Color.Gold:Color.FromArgb(94,85,114),hover?3:1);g.FillEllipse(b,2,2,Width-5,Height-5);g.DrawEllipse(p,2,2,Width-5,Height-5);using var f=new Font("Segoe UI Symbol",23,FontStyle.Bold);using var brush=new SolidBrush(Color.FromArgb(190,170,250));using var format=new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center};g.DrawString(symbol,f,brush,ClientRectangle,format);}}
sealed class SystemStats {
 [StructLayout(LayoutKind.Sequential)]class Memory {public uint Length=(uint)Marshal.SizeOf<Memory>();public uint Load;public ulong Total,Available,PageTotal,PageAvailable,VirtualTotal,VirtualAvailable,Extended;}
 [DllImport("kernel32")]static extern bool GlobalMemoryStatusEx([In,Out]Memory value);
 [DllImport("kernel32")]static extern bool GetSystemTimes(out ulong idle,out ulong kernel,out ulong user);
 ulong oldIdle,oldTotal;long oldDown,oldUp;DateTime previous=DateTime.UtcNow;public double Cpu,Ram,Storage,Down,Up;public ulong UsedMemory;public long FreeStorage;
 public void Update(){if(GetSystemTimes(out var idle,out var kernel,out var user)){ulong total=kernel+user;if(oldTotal>0&&total>oldTotal)Cpu=Math.Clamp(100d*(1-(double)(idle-oldIdle)/(total-oldTotal)),0,100);oldIdle=idle;oldTotal=total;}var memory=new Memory();if(GlobalMemoryStatusEx(memory)){Ram=memory.Load;UsedMemory=memory.Total-memory.Available;}try{var drive=new DriveInfo(Path.GetPathRoot(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile))!);FreeStorage=drive.AvailableFreeSpace;Storage=100d*(drive.TotalSize-drive.AvailableFreeSpace)/drive.TotalSize;}catch{}try{long down=0,up=0;foreach(var network in NetworkInterface.GetAllNetworkInterfaces().Where(n=>n.OperationalStatus==OperationalStatus.Up&&n.NetworkInterfaceType!=NetworkInterfaceType.Loopback)){var stats=network.GetIPv4Statistics();down+=stats.BytesReceived;up+=stats.BytesSent;}double seconds=(DateTime.UtcNow-previous).TotalSeconds;if(oldDown>0&&seconds>0){Down=Math.Max(0,(down-oldDown)*8/1e6/seconds);Up=Math.Max(0,(up-oldUp)*8/1e6/seconds);}oldDown=down;oldUp=up;previous=DateTime.UtcNow;}catch{}}
}
class MonitorCard:RoundedPanel {public SystemStats Stats{get;}=new();protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);var g=e.Graphics;using var f=new Font("Segoe UI",10,FontStyle.Bold);using var b=new SolidBrush(Ui.Muted);int y=28;void Line(string text,double percent,Color color){g.DrawString(text,f,b,18,y);y+=27;using var track=new SolidBrush(Color.FromArgb(60,48,77));using var fill=new SolidBrush(color);g.FillRectangle(track,18,y,Math.Max(1,Width-36),7);g.FillRectangle(fill,18,y,(float)((Width-36)*Math.Clamp(percent,0,100)/100),7);y+=25;}Line($"CPU: {Stats.Cpu:0}%",Stats.Cpu,Color.Coral);Line($"RAM: {Stats.Ram:0}% ({Stats.UsedMemory/1073741824d:0.0} GB)",Stats.Ram,Color.MediumSeaGreen);Line("GPU: Not available",0,Color.DeepSkyBlue);Line($"Storage: {Stats.Storage:0}% ({Stats.FreeStorage/1073741824d:0} GB free)",Stats.Storage,Color.Goldenrod);g.DrawString($"↓ {Stats.Down:0.0} Mbps    ↑ {Stats.Up:0.0} Mbps",f,b,18,y+5);g.DrawString("TEMP: N/A     MEMORY: OK",f,b,18,y+40);}}






